<?php
namespace App\Controllers;use App\Models\Book;use App\Core\Security;use App\Core\Auth;
final class BookController{private Book $m;public function __construct(){$this->m=new Book();}public function index():void{$books=$this->m->all();$title='Book Catalog';require BASE_PATH.'/app/Views/books/index.php';}public function create():void{Auth::requireRole(['administrator','librarian']);$categories=$this->m->categories();if($_SERVER['REQUEST_METHOD']==='POST'&&Security::validCsrf($_POST['_csrf']??null)){$this->m->create($_POST);Security::flash('success','Book added to inventory.');Security::redirect('books');}$title='Add Book';require BASE_PATH.'/app/Views/books/form.php';}public function delete():void{Auth::requireRole(['administrator','librarian']);if(!Security::validCsrf($_POST['_csrf']??null)){Security::flash('danger','Request expired.');Security::redirect('books');}$id=(int)$_POST['id'];$db=Database::connection();$checks=['checkouts','acquisitions','reservations','stock_checks'];foreach($checks as $table){try{$s=$db->prepare("SELECT COUNT(*) FROM `$table` WHERE book_id=?");$s->execute([$id]);if((int)$s->fetchColumn()>0){Security::flash('danger','This book cannot be deleted because it has related history.');Security::redirect('books');}}catch(\PDOException $e){}}$db->prepare('DELETE FROM books WHERE id=?')->execute([$id]);Security::flash('success','Book deleted.');Security::redirect('books');}}
